// logo.js
// Shared brand-mark markup for every place "Klandestina" renders as a
// clickable logo rather than body prose: the desktop topbar
// (#brand-mark), the mobile fixed topbar, the mobile hamburger nav
// overlay, and the footer. One function so the markup, fallback
// behavior, and alt text are defined once instead of four times.
//
// The mark itself is the donkey mascot centered on a cream circle badge
// (images/logo/badge.{png,webp}, generated by scripts/build-logo.mjs
// from the untouched images/logo/donkey.png — the donkey's own black
// body would disappear against the site's navy without the cream behind
// it). Sizing is CSS (.brand-badge-img, scoped per placement in
// style.css), same "one file, size via CSS" approach the old wordmark
// image used.

const TEXT_MARK_FALLBACK = "Klande&middot;stina";

/**
 * @param {Object} site - from data/site.json
 * @param {Object} [opts]
 * @param {string} [opts.homeHref] - "/" or "/fi/" depending on the active language, so the
 *   logo always links to home IN the language currently being viewed, not always English.
 * @param {boolean} [opts.withWordmark] - also show "KLANDESTINA" as text next to the badge
 *   (the desktop topbar only, per the task — everywhere else is badge-only).
 * @returns {string} HTML to place inside an existing brand-mark container
 *   (#brand-mark, .mobile-topbar-brand, .mobile-nav-brand, .footer-logo).
 */
export function brandLogoHTML(site, { homeHref = "/", withWordmark = false } = {}) {
  if (!site) {
    return `<a href="${homeHref}" aria-label="Klandestina">${TEXT_MARK_FALLBACK}</a>`;
  }

  // If the badge files are missing or fail to decode, onerror swaps the
  // broken <img> for the same plain text mark the site used before any
  // logo file existed — degrades gracefully instead of a broken-image
  // icon or an empty gap in the nav/footer. Escaped for the inline
  // handler the same way the original single-image version was.
  const escapedFallback = TEXT_MARK_FALLBACK.replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  const badge = `
    <picture>
      <source srcset="/images/logo/badge.webp" type="image/webp">
      <img
        class="brand-badge-img" src="/images/logo/badge.png" alt="Klandestina"
        width="256" height="256" onerror="this.closest('picture').outerHTML='${escapedFallback}'"
      >
    </picture>`;
  const wordmark = withWordmark ? `<span class="brand-wordmark" aria-hidden="true">KLANDESTINA</span>` : "";

  return `<a href="${homeHref}" class="brand-link">${badge}${wordmark}</a>`;
}
